/**
 * Phase 1 acceptance: surfaces, areas and volumes match EnergyPlus
 * (tests/oracles, generated by tools/make_oracles.py) within 0.5 %.
 */
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { buildGeometry } from '../src/core/geometry/build';
import { openFile } from '../src/core/session';
import { diskSchemaLoader, fileBuffer, ROOT } from './helpers';

interface OracleSurface {
  class: string;
  grossArea?: number;
  azimuth?: number;
  tilt?: number;
  vertices?: number[][];
}
interface Oracle {
  zones: Record<string, { volume: number; floorArea: number; ceilingHeight: number }>;
  surfaces: Record<string, OracleSurface>;
}

const loader = diskSchemaLoader();
const oracleDir = resolve(ROOT, 'tests/oracles');
const cases = readdirSync(oracleDir)
  .filter((f) => f.endsWith('.json'))
  .map((f) => f.replace(/\.json$/, ''))
  .map((stem) => {
    const idf = ['examples', 'tests/fixtures/geometry', 'tests/fixtures/windows']
      .map((dir) => `${dir}/${stem}.idf`)
      .find((p) => existsSync(resolve(ROOT, p)));
    return [stem, idf] as const;
  })
  .filter((c): c is readonly [string, string] => Boolean(c[1]));

const relClose = (a: number, b: number, rel = 0.005, abs = 0.01) =>
  Math.abs(a - b) <= Math.max(abs, rel * Math.abs(b));
const angleClose = (a: number, b: number, tol = 0.5) => {
  const d = Math.abs(((a - b + 540) % 360) - 180);
  return d <= tol;
};

describe.each(cases)('%s', (stem, idf) => {
  it('matches EnergyPlus surfaces and zones', async () => {
    const oracle: Oracle = JSON.parse(readFileSync(resolve(oracleDir, `${stem}.json`), 'utf8'));
    const session = await openFile({ name: idf, buffer: fileBuffer(idf) }, loader);
    const geometry = buildGeometry(session.model, session.schema);
    const problems: string[] = [];
    let compared = 0;
    // EnergyPlus upper-cases names, except suffixes it adds (e.g. "<FIN> Left").
    const byLower = new Map(Object.entries(oracle.surfaces).map(([k, v]) => [k.toLowerCase(), v]));

    for (const s of geometry.surfaces) {
      const ref = byLower.get(s.name.toLowerCase());
      if (!ref) {
        problems.push(`${s.name}: not in EnergyPlus output`);
        continue;
      }
      compared++;
      if (ref.grossArea !== undefined && !relClose(s.area, ref.grossArea)) {
        problems.push(`${s.name}: area ${s.area.toFixed(3)} vs ${ref.grossArea}`);
      }
      if (ref.tilt !== undefined && !angleClose(s.tilt, ref.tilt)) {
        problems.push(`${s.name}: tilt ${s.tilt.toFixed(2)} vs ${ref.tilt}`);
      }
      if (ref.azimuth !== undefined && !angleClose(s.azimuth, ref.azimuth)) {
        problems.push(`${s.name}: azimuth ${s.azimuth.toFixed(2)} vs ${ref.azimuth}`);
      }
      if (ref.vertices) {
        const ok =
          ref.vertices.length === s.vertices.length &&
          ref.vertices.every((v, i) =>
            v.every((c, k) => Math.abs(c - (s.vertices[i]?.[k] ?? Number.NaN)) <= 0.0151),
          );
        if (!ok) {
          const ours = s.vertices.map((v) => v.map((c) => c.toFixed(2)).join(',')).join(' | ');
          const theirs = ref.vertices.map((v) => v.join(',')).join(' | ');
          problems.push(`${s.name}: vertices\n   ours ${ours}\n   E+   ${theirs}`);
        }
      }
    }

    for (const z of geometry.zones) {
      const ref = oracle.zones[z.name.toUpperCase()];
      if (!ref) {
        problems.push(`zone ${z.name}: not in EnergyPlus output`);
        continue;
      }
      if (!relClose(z.floorArea, ref.floorArea)) {
        problems.push(`zone ${z.name}: floor area ${z.floorArea.toFixed(3)} vs ${ref.floorArea}`);
      }
      if (!relClose(z.ceilingHeight, ref.ceilingHeight)) {
        problems.push(
          `zone ${z.name}: ceiling height ${z.ceilingHeight.toFixed(3)} vs ${ref.ceilingHeight}`,
        );
      }
      if (!relClose(z.volume, ref.volume)) {
        problems.push(
          `zone ${z.name}: volume ${z.volume.toFixed(3)} (${z.volumeSource}) vs ${ref.volume}`,
        );
      }
    }

    expect(compared).toBeGreaterThan(0);
    expect(problems.slice(0, 15).join('\n'), `${problems.length} differences`).toBe('');
  });
});

describe('envelope by orientation (D2)', () => {
  const columns = {
    Total: 'Total',
    North: 'North (315 to 45 deg)',
    East: 'East (45 to 135 deg)',
    South: 'South (135 to 225 deg)',
    West: 'West (225 to 315 deg)',
  } as const;

  it.each(cases.filter(([stem]) => existsSync(resolve(ROOT, `examples/${stem}.idf`))))(
    '%s matches the EnergyPlus window-wall ratio table',
    async (stem, idf) => {
      const { buildingSummary } = await import('../src/core/summary');
      const oracle = JSON.parse(readFileSync(resolve(oracleDir, `${stem}.json`), 'utf8'));
      const table = oracle.building.windowWallRatio;
      const session = await openFile({ name: idf, buffer: fileBuffer(idf) }, loader);
      const summary = buildingSummary(
        session.model,
        session.schema,
        buildGeometry(session.model, session.schema),
      );
      for (const row of summary.envelope) {
        const column = columns[row.orientation];
        expect(
          relClose(row.grossWallArea, table['Gross Wall Area'][column]),
          `${column} wall`,
        ).toBe(true);
        expect(
          relClose(row.windowArea, table['Window Opening Area'][column]),
          `${column} window`,
        ).toBe(true);
      }
    },
  );
});
